      (* [comment removed for export] *)
      Lemma tr_after_printf : forall (rn k : nat) (fxc : FPState) regs m mo sC,
        (1 <= rn)%nat -> (k + rn = calls + 1)%nat -> (1 <= k)%nat ->
        lstate k (Z.of_nat rn) regs m mo sC -> getr regs 19 = Z_to_bv 64 0 -> FP.frm0 (@fp_csr fxc) ->
